const mod = await import('@remix-run/web-fetch');
const fetchFn = mod.default || mod.fetch || mod;
const url = process.env.URL;
if (!url) throw new Error('URL not provided');
globalThis.response = await fetchFn(url);

const resp = globalThis.response;
if (!resp) throw new Error('No response from fetch step');
globalThis.status = resp.status;
globalThis.body = await resp.text();
